{"concepto": "LayerNorm (normalización de capas)", "enunciado": "$$\\text{LayerNorm}(x) = \\gamma \\cdot \\frac{x - \\mu}{\\sqrt{\\sigma^2 + \\epsilon}} + \\beta$$", "problema": "normalizar distribuciones de activación dentro de la red", "limite": "introducida post-norm causaba inestabilidad de gradientes en redes profundas", "patron": "estandarizar estadísticas locales de activación usando media y varianza aprendibles", "linea": 240}
{"concepto": "RMS Norm (normalización por raíz cuadrática media)", "enunciado": "$$\\text{RMSNorm}(x) = \\gamma \\cdot \\frac{x}{\\sqrt{\\frac{1}{d}\\sum_{i=1}^{d} x_i^2 + \\epsilon}}$$", "problema": "normalizar de forma más eficiente que LayerNorm sin perder calidad", "limite": "no centra la distribución (omite sustracción de media)", "patron": "estandarizar por una estadística robusta (RMS) sin aprender desplazamientos", "linea": 251}
{"concepto": "GELU (activación lineal de unidades Gaussian Error)", "enunciado": "$$\\text{GELU}(x) = x \\cdot \\Phi(x)$$", "problema": "proporcionar no-linealidad suave en puntos de transición que ReLU", "limite": "más costosa computacionalmente que ReLU", "patron": "ponderar entrada por probabilidad acumulada de distribución normal", "linea": 325}
{"concepto": "Swish / SiLU (activación Sigmoid Linear Unit)", "enunciado": "$$\\text{Swish}(x) = x \\cdot \\sigma(x)$$", "problema": "proporcionar suavidad cerca de cero con auto-gating", "limite": "más costosa que ReLU", "patron": "ponderar entrada por salida de función sigmoid para auto-modulación", "linea": 326}
{"concepto": "GLU - Gated Linear Unit (unidad lineal con puerta)", "enunciado": "$$\\text{GLU-FFN}(x) = (\\text{activation}(xW_1) \\odot xV) W_2$$", "problema": "permitir que la red aprenda dinámicamente qué características pasar o bloquear", "limite": "introduce matriz adicional V que aumenta parámetros", "patron": "descomponer salida en dos ramas: una con transformación no-lineal, otra como multiplicador gating", "linea": 344}
{"concepto": "SwiGLU (SwiGLU variant)", "enunciado": "$$\\text{SwiGLU}(x) = (\\text{Swish}(xW_1) \\odot xV) W_2$$", "problema": "combinar suavidad de Swish con ventajas de mecanismo gating", "limite": "parámetro adicional V requiere rebalanceo de capas FFN", "patron": "aplicar activación suave en rama de transformación, usar otra rama como compuerta multiplicativa", "linea": 357}
{"concepto": "Pre-norm (normalización pre-residual)", "enunciado": "LayerNorm colocado antes de rama residual dentro de bloque Transformer", "problema": "estabilizar flujo de gradientes en redes profundas", "limite": "cambia el comportamiento de la conexión residual", "patron": "normalizar entrada a operación antes de combinarla con conexión identidad", "linea": 164}
{"concepto": "Serial layers (capas seriales)", "enunciado": "$$x_{out} = x + \\text{MLP}(x + \\text{Attn}(x))$$", "problema": "permitir composición secuencial de operaciones de atención y transformación lineal", "limite": "menor eficiencia de sistema que paralelo", "patron": "ejecutar operaciones en secuencia, realimentando salida de una como entrada de siguiente", "linea": 412}
{"concepto": "Parallel layers (capas paralelas)", "enunciado": "$$x_{out} = x + \\text{Attn}(x) + \\text{MLP}(x)$$", "problema": "mejorar eficiencia computacional ejecutando operaciones simultáneamente", "limite": "menor poder expresivo que composición serial", "patron": "ejecutar operaciones independientes en paralelo y acumular resultados en residual", "linea": 414}
{"concepto": "RoPE - Rotary Position Embedding (incrustación de posición rotacional)", "enunciado": "$$\\langle f(x, i), f(y, j) \\rangle = g(x, y, i - j)$$", "problema": "codificar información de posición tal que similitud entre vectores dependa solo de distancia relativa", "limite": "requiere frecuencias base apropiadas para generalizar a secuencias más largas que entrenamiento", "patron": "aplicar transformación dependiente de posición que modifica solo dimensiones relativas entre vectores", "linea": 447}
{"concepto": "RoPE rotation matrix (matriz de rotación RoPE)", "enunciado": "$$R_{\\theta, m} = \\begin{pmatrix} \\cos m\\theta_1 & -\\sin m\\theta_1 & & \\\\ \\sin m\\theta_1 & \\cos m\\theta_1 & & \\\\ & & \\ddots & \\\\ & & & \\cos m\\theta_{d/2} & -\\sin m\\theta_{d/2} \\\\ & & & \\sin m\\theta_{d/2} & \\cos m\\theta_{d/2} \\end{pmatrix}$$", "problema": "implementar rotación de vectores por ángulo dependiente de posición", "limite": "operación fija, no entrenable", "patron": "descomponer espacio de alta dimensión en pares de dimensiones 2D independientes, rotar cada par por frecuencia distinta", "linea": 469}
{"concepto": "RoPE frequency (frecuencia RoPE)", "enunciado": "$$\\theta_i = 10000^{-2i/d}$$", "problema": "asignar diferentes escalas temporales a diferentes pares de dimensiones", "limite": "heurística sin justificación teórica completa", "patron": "usar escala logarítmica para cubrir rango exponencial de frecuencias", "linea": 473}
{"concepto": "FFN dimension ratio - non-gated (ratio de dimensiones FFN no-gated)", "enunciado": "$$d_{ff} = 4 \\times d_{model}$$", "problema": "determinar ancho de capa oculta en función de dimensión del modelo", "limite": "específico para activaciones no-gated", "patron": "escalar dimensión intermedia proporcionalmente a dimensión del modelo", "linea": 530}
{"concepto": "FFN dimension ratio - GLU (ratio de dimensiones FFN con GLU)", "enunciado": "$$d_{ff} = \\frac{8}{3} d_{model} \\approx 2.67 \\times d_{model}$$", "problema": "mantener total de parámetros constante cuando GLU introduce matriz gating adicional", "limite": "específico para activaciones gated", "patron": "reducir dimensión intermedia por factor 2/3 para compensar matriz gating extra", "linea": 531}
{"concepto": "Attention head dimension relationship (relación de dimensión de cabeza de atención)", "enunciado": "$$d_{model} = n_{heads} \\times d_{head}$$", "problema": "mantener consistencia de dimensiones en mecanismo de atención multi-cabeza", "limite": "asume cociente exacto 1:1", "patron": "distribuir dimensionalidad modelo entre cabezas de forma uniforme", "linea": 564}
{"concepto": "Aspect Ratio (ratio de forma del modelo)", "enunciado": "$$\\text{Aspect Ratio} = \\frac{d_{model}}{n_{layers}}$$", "problema": "determinar óptimo equilibrio entre ancho y profundidad del modelo", "limite": "ratio óptimo aproximadamente 128 para rango de escala 50M-1.5B parámetros", "patron": "mantener relación fija entre dimensiones modelo y número de capas", "linea": 576}
{"concepto": "Z-loss (pérdida Z para estabilidad softmax)", "enunciado": "$$\\mathcal{L}_{total} = \\mathcal{L}_{CE} + \\alpha \\cdot \\log^2 Z(x)$$", "problema": "estabilizar cálculo del factor de normalización softmax en capa de salida", "limite": "introducye hiperparámetro adicional α", "patron": "penalizar desviación de factor de normalización de su valor estable (1) mediante término auxiliar regularizador", "linea": 695}
{"concepto": "QK-norm (normalización de Query-Key)", "enunciado": "$$\\text{attn}(Q, K, V) = \\text{softmax}\\left(\\frac{\\text{Norm}(Q) \\cdot \\text{Norm}(K)^T}{\\sqrt{d_k}}\\right) V$$", "problema": "estabilizar magnitudes de scores de atención antes de softmax", "limite": "costo computacional adicional de normalización", "patron": "normalizar inputs a multiplicación de matrices antes de operación potencialmente inestable", "linea": 718}
{"concepto": "Soft capping (truncamiento suave de logits)", "enunciado": "$$\\text{logits}_{capped} = \\text{cap} \\cdot \\tanh\\left(\\frac{\\text{logits}}{\\text{cap}}\\right)$$", "problema": "limitar magnitud de logits de atención para evitar inestabilidad numérica", "limite": "puede reducir expresividad; efectos mixtos en calidad según modelos", "patron": "comprimir rango de valores mediante función suave acotada que preserva orden relativo", "linea": 728}
{"concepto": "KV cache size (tamaño de cache de Key-Value)", "enunciado": "$$2 \\times n_{layers} \\times n_{heads} \\times d_{head} \\times N$$", "problema": "cuantificar costo de memoria en inferencia autoregresiva", "limite": "crece linealmente con longitud de secuencia N", "patron": "almacenar proyecciones pasadas para evitar recálculos, con huella de memoria proporcional a contexto histórico", "linea": 784}
{"concepto": "Grouped-Query Attention (GQA - Atención de Query Agrupada)", "enunciado": "H query heads comparten G key-value heads donde 1 < G < H", "problema": "reducir cache de KV en inferencia sin perder demasiada capacidad expresiva", "limite": "compromiso entre eficiencia y calidad de modelo", "patron": "factorizar proyecciones en múltiples grupos, reduciendo redundancia mientras preserva diversidad de proyecciones", "linea": 801}
{"concepto": "Multi-Query Attention (MQA - Atención Multi-Query)", "enunciado": "H query heads comparten 1 key-value head", "problema": "maximizar reducción de cache de KV para máxima eficiencia de inferencia", "limite": "posible degradación de calidad de modelo", "patron": "factorización extrema donde todas cabezas query reutilizan proyecciones KV únicas", "linea": 800}
{"concepto": "Sliding Window Attention (Atención de Ventana Deslizante)", "enunciado": "Cada capa solo atiende a tokens dentro ventana local de tamaño fijo", "problema": "escalar a contextos largos con costo computacional controlado", "limite": "receptive field efectivo limitado a ventana size × número de capas", "patron": "limitar radio de interacción a vecindario local, acumulando dependencias de largo alcance a través de capas", "linea": 827}
